import{z as A,x as B,o as t,c as d,q as n,j as i,D as r,d as E,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"酸与淬灭剂的计数噪声","description":"","frontmatter":{"title":"酸与淬灭剂的计数噪声","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/acid-quencher-counting.md","filePath":"litho/acid-quencher-counting.md","lastUpdated":1791063341000}'),p={name:"litho/acid-quencher-counting.md"};function h(u,a,D,c,m,f){const l=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="酸与淬灭剂的计数噪声" tabindex="-1">酸与淬灭剂的计数噪声 <a class="header-anchor" href="#酸与淬灭剂的计数噪声" aria-label="Permalink to &quot;酸与淬灭剂的计数噪声&quot;">​</a></h1><div class="epigraph"><p>平均场把酸和碱写成连续浓度；纳米线上它们是可数的分子。泊松涨落在争夺带上直接变成边的抖。</p><footer>—— 据 Naulleau 对材料离散与光子噪声的区分；Gallatin 对酸计数与 LER 的公开论述整理</footer></div><p><a href="/litho/resist-polymer-mw">上一课</a>把平均分子量写成溶解与 LER 的材料前置。平均场课序到此结束。缺口是离散：<a href="/litho/euv-stochastics">随机效应</a>已经从光子 \\(N\\) 讲过 LCDU 与缺孔；本课补化学侧——酸与淬灭剂分子数。<a href="/litho/pag-quencher">PAG 与淬灭剂</a>的一对浓度，现在变成一对计数。二次电子把吸收事件涂开，留给<a href="/litho/secondary-electron-blur-model">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>体积 \\(V\\) 里平均 \\(\\bar n_h=\\bar h V\\) 颗酸、\\(\\bar n_q=\\bar q V\\) 颗碱。泊松方差等于均值。争夺带的 \\(V\\) 由厚度 × 相关面积决定，EUV 薄胶、细线时 \\(\\bar n\\) 可以落到几十。局部碱多一颗，阈值抬；酸少一颗，脱保护不够。连续场 RD 对此输出平滑边，硅片上却是毛边与偶发桥断。</p><p><span class="marginnote">术语翻译：泊松涨落是离散个体的天生抖动——就像数骰子点数，平均摇出 \\(n\\) 个点，实际点数天然上下差 \\(\\sqrt{n}\\) 的量级。它不是仪器没调好，而是「分子可数」这件事本身的数学后果。</span></p><p>缺口不是再算 92 eV 光子面密度，而是：即使光子 \\(N\\) 很大（ArF），PAG / 碱加载若低，化学计数仍醒。EUV 上两者一起小，不能只用光子项签核胶。</p><h3 id="有效体积不是像素" tabindex="-1">有效体积不是像素 <a class="header-anchor" href="#有效体积不是像素" aria-label="Permalink to &quot;有效体积不是像素&quot;">​</a></h3><p>把仿真网格当成独立体积会高估噪声：酸扩散与电子核让相邻体积相关，有效 \\(V\\) 变大，相对涨落变小，同时边被糊。Gallatin 一类分析把模糊写成既降方差又降分辨率的同一标长。本课先承认计数，核的形状下一课再写。</p><p><span class="marginnote">淬灭剂加载升高，\\(\\bar n_q\\) 升，相对涨落降，但灵敏度掉、有效 \\(N\\) 酸要更多。这是 RLS 在分子账本上的第一笔，三角课再收。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计：用加载 wt% 与分子量换成分子密度，乘争夺带体积，得 \\(\\bar n\\)。比较光子吸收数与产酸数：量子产率或电离增益把两者耦起来，但方差不是同一泊松——产酸是分支过程，Fano 因子可以不是 1。工程上仍用 LCDU / LER 对剂量与对加载的两组斜率来拆光子项与化学项：加剂量主要压光子；加 PAG/碱（固定剂量）压化学，直到团聚或吸收饱和。</p><p><span class="marginnote">常见误区：初学者容易以为「光子够多就稳了」。若 PAG 与碱加载偏低，化学计数照样抖——ArF 上化学离散常主导 LWR，签核不能只算光子那本账。</span></p><p>Naulleau 强调实验要把掩模固定图案与重复曝光涨落分开。化学计数属于后者。</p>',14)),(t(),i(s,null,{default:r(()=>[o(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PH%5B%22%E5%85%89%E5%AD%90%E5%90%B8%E6%94%B6%22%5D%20--%3E%20H%5B%22%E9%85%B8%E5%88%86%E5%AD%90%E6%95%B0%22%5D%0A%20%20PAG%5B%22PAG%20%E5%8A%A0%E8%BD%BD%22%5D%20--%3E%20H%0A%20%20Q%5B%22%E7%A2%B1%E5%88%86%E5%AD%90%E6%95%B0%22%5D%20--%3E%20NET%5B%22%E5%B1%80%E9%83%A8%E6%9C%89%E6%95%88%E9%85%B8%22%5D%0A%20%20H%20--%3E%20NET%0A%20%20NET%20--%3E%20EDGE%5B%22%E4%BA%89%E5%A4%BA%E5%B8%A6%E8%BE%B9%E6%8A%96%22%5D%0A%20%20V%5B%22%E6%9C%89%E6%95%88%E4%BD%93%E7%A7%AF%20%2F%20%E6%A0%B8%22%5D%20--%3E%20NET%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("曝光把 PAG 抽样成酸位置；PEB 中和把酸碱成对湮灭。剩余有效酸的涨落在阈值模型里被 \\(\\partial x/\\partial h\\) 放大，该导数就是 ILS / 化学衬度的倒数。"),e("a",{href:"/litho/acid-diffusion-lwr"},"酸扩散"),E(" 把单颗酸的影响摊成核，降低高频抖、增加低频相关。碱的空间分布若团聚，会出现「固定」的化学掩模，重复曝光仍相关——那是材料均匀性，不是泊松。")],-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：争夺带里平均 25 颗酸时，相对涨落约 \\(1/\\sqrt{25}=20\\%\\)；凑到 2500 颗才降到 2%。从几十颗到几千颗，边抖就差一个数量级——这就是为什么细线薄胶先把「可数的分子」用完。")],-1)),(t(),i(s,null,{default:r(()=>[o(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E4%BA%89%E5%A4%BA%E5%B8%A6%E6%9C%89%E6%95%88%E4%BD%93%E7%A7%AF%20V%22%5D%20--%3E%20N%5B%22%E5%B9%B3%E5%9D%87%E5%88%86%E5%AD%90%E6%95%B0%20n%22%5D%0A%20%20N%20--%3E%20SQ%5B%22%E7%9B%B8%E5%AF%B9%E6%B6%A8%E8%90%BD%20%E2%88%9D%201%2F%E2%88%9An%22%5D%0A%20%20SQ%20--%3E%20RES%5B%22%E5%89%A9%E4%BD%99%E6%9C%89%E6%95%88%E9%85%B8%E6%B6%A8%E8%90%BD%22%5D%0A%20%20RES%20--%3E%20AMP%5B%22%E9%98%88%E5%80%BC%E5%AF%BC%E6%95%B0%E6%94%BE%E5%A4%A7%22%5D%0A%20%20AMP%20--%3E%20LER%5B%22LER%20%2F%20LCDU%22%5D%0A%20%20BLUR%5B%22%E6%89%A9%E6%95%A3%20%2F%20%E7%94%B5%E5%AD%90%E6%A8%A1%E7%B3%8A%E6%A0%B8%22%5D%20--%3E%20V%0A%20%20BLUR%20--%3E%20COR%5B%22%E9%82%BB%E5%9F%9F%E7%9B%B8%E5%85%B3%E5%8D%87%E3%80%81%E9%AB%98%E9%A2%91%E6%8A%96%E9%99%8D%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>聚合物链尺寸是第三套计数，上一课已前置。本课对象明确为酸与碱，避免把所有 LER 写成一种分子。</p><p><span class="marginnote">ArF 光子多，化学离散与聚合物团聚常主导 LWR。EUV 光子项上升，但不等于化学项消失。拆实验不能省。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编每立方纳米「标准酸数」。不把某一 SPIE 表的分子密度当节点规格。下一课的二次电子核改有效 \\(V\\) 与空间相关，本课的泊松还是点过程。Monte Carlo 课会按本课密度抽样。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>酸与碱在争夺带里是可数的；连续浓度是它们的均值。</li><li>有效体积由核决定，网格像素不是独立体积。</li><li>加剂量与加加载压的是不同泊松源，要用斜率拆。</li><li>ArF 也可由化学计数主导 LWR。</li><li>出处：Naulleau 对材料 vs 光子离散；Gallatin 对酸计数与模糊。</li></ul>',6))])}const P=A(p,[["render",h]]);export{b as __pageData,P as default};
